 # "Fri, 28 Aug 2026 00:00:00 +0000". Every editable field is replayed
 # through serialize() below, so a default this parser cannot read came back
 # as None and was submitted as empty subfields -- silently clearing a date
 # the caller never mentioned. Drop a leading weekday token and accept a
 # month name so that replay round-trips.
 if parts[0].endswith(",") and not parts[0][:-1].isdigit():
 parts = parts[1:]
 if not parts:
 return None
 datepart = parts[0]
 timepart = parts[1] if len(parts) > 1 else ""
 sep = "-" if "-" in datepart else ("/" if "/" in datepart else None)
 if sep is None:
 # "28 Aug 2026 00:00:00 +0000": day, month name and year are separate tokens.
 if len(parts) >= 3 and datepart.isdigit():
 mon = _MCP_MONTHS.get(parts[1][:3].lower())
 if mon is not None and parts[2].isdigit():
