 if tp_src and ":" in tp_src:
 tp = tp_src.split(":")
 try:
 h = int(tp[0])
 mi = int(tp[1]) if len(tp) > 1 else 0
 except Exception:
 h = mi = 0
 return (y, m, d, h, mi)
 return None
