 def serialize(fk, fd, value, uid):
 ftype = fd.get("type", "")
 default = fd.get("default", "")
 form_key = "field_%s" % fk
 r = {}
 if ftype == "RelationStringField":
 val = value if value is not None else default
 if isinstance(val, list):
 val = val[0] if val else ""
