 rid = fd.get("relation_field_id", "")
 if rid:
 if uid is not None:
 r[rid] = uid
 elif value is None:
 # Field is only being replayed, not edited: keep the current link.
 ex = fd.get("relation_item_uid", [])
 if ex:
 r[rid] = str(ex[0])
 # Explicitly supplied but unresolved (or ""): send no uid, so ERP5
 # validates the string itself instead of silently keeping the old
 # link and reporting success. Whether the link really got made is
 # re-checked after Base_edit below.
 elif ftype == "FloatField":
 r[form_key] = render_float(fd, value if value is not None else default)
 elif ftype == "IntegerField":
 val = value if value is not None else default
 r[form_key] = "" if val is None or val == "" else str(val)
 elif ftype == "CheckBoxField":
 r[form_key] = value if value is not None else default
