 def marshal(fd_):
 out = {}
 for k, v in fd_.items():
 if k.endswith(":int"):
 try:
 out[k[:-4]] = int(v)
 except Exception:
 out[k[:-4]] = 0
 elif k.endswith(":list"):
 out[k[:-5]] = v if isinstance(v, list) else ([v] if v not in (None, "") else [])
 elif k.endswith(":float"):
 try:
 out[k[:-6]] = float(v)
 except Exception:
 out[k[:-6]] = 0.0
 else:
 out[k] = v
 return out
 def _mcp_native(v):
 # REQUEST.form values of a real HTTP submit are native strings: utf-8
 # encoded bytes on Python 2, text on Python 3. JSON decoding always yields
 # text, so on Python 2 it must be encoded -- else the unicode leaks into the
 # stored property (a LinesField then holds a list of unicode) and
 # unrestrictedTraverse iterates over the characters of such a path, which
 # breaks Business Template build. On Python 3 text is already native and
 # must be left untouched.
 # Numbers get the same treatment for the same reason: a submit carries
 # "1.5", never 1.5, and validators that call string methods on the value
 # (normalizeFullWidthNumber does value.decode) raise AttributeError on a
 # float or an int. bool is checked before int because it is a subclass of
 # it -- str(False) would be "False", which BooleanValidator reads as true.
 if isinstance(v, (list, tuple)):
 return [_mcp_native(x) for x in v]
 if isinstance(v, dict):
 return dict([(_mcp_native(k2), _mcp_native(v2)) for k2, v2 in v.items()])
 if isinstance(v, str):
 return v
 if hasattr(v, "encode"): # Python 2 unicode
 return v.encode("utf-8")
 if v is None:
 return ""
 if isinstance(v, bool):
 return "1" if v else "0"
 if isinstance(v, (int, float)):
 return str(v)
 return v
